WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (705::BIGINT, 'El profesor es muy buen docente y se nota que sabe bastante. Me gusta mucho la dinámica de las clases y como el profesor reta a los estudiantes y dice las cosas como son. Eso me parece importante en un profesor.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2026-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'c499f885f5fee3e5013e7b4ef11300dbf54fad151c91095894fce7cf78fb7ed7'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Por la naturaleza del curso, es básicamente dedicado a investigación y a entender el concepto de cómo funciona todo. El profe se nota que sabe mucho y trata de hacer las clases muy amenas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '1b6fb4d807fe712e3af1bfff8efe2ea61bfaa4f79cff9d6ba68257ad3f8112a9'::TEXT, ARRAY[3069]::BIGINT[]),
    (705::BIGINT, 'Muy buen profesor. Él es claro en cuanto a lo que espera de los estudiantes, si es desordenado en la resolución de problemas le va mal, el curso como tal es bastante complicado pero él cumple en hacerlo accesible. Pasa lista de vez en cuando, y beneficia demasiado ir regularmente a las clases.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'fcb8d5986004a31288585c3a7d3d8e6a6f42a2d4b13ee14f70d86f40b5edb29e'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Muy buen profe que lamentablemente da un curso bastante díficil. Es muy comico y las clases son rápidas y al grano, por lo que es recomendable preguntar TODA duda y tener la materia al día, sería bueno que el profe diera más material para estudiar pero por lo general da el curso muy bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '36e80317fb686022bbebceee8daf12aa2ec4d60b5fbbf034d2b5d7bc0cd29448'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Buen profe que es honesto con la dificultad del curso pero también da los consejos de como pasarlo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-01-19T00:00:00+00:00'::TIMESTAMPTZ, '7457ca1de43adf4131e29696e3597be753ff5af94d805f64005ee0532f4027a1'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2025-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'a6b1fd6a7662b43434a5e0aab4142dd701df9bee3df8e916a1ace87eb3d2d4df'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Al inicio puede sentirse intimidante pero en realidad es bastante tuanis. Es un curso difícil y pesado, y eso mismo dicta el esfuerzo que usted le va a tener que dedicar. Hace exámenes bastante difíciles pero se compensa con la opción de las tutorías. Debe ser muy ordenado con todo con el profe.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2025-07-29T00:00:00+00:00'::TIMESTAMPTZ, '3502550aef10a54dd6c405dabdc67136f6bc42bd67380873be7f48c1f161c9a3'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Es muy muy bueno, solo que hay que saber por donde agarrarlo. La materia la explica de forma super clara y 0 problemas con que usted no entienda, se equivoque o pregunte EN CLASE. Algo que tiene es que al inicio da como miedo, pero el con el tiempo uno se da cuenta que realmente quiere ayudar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, '425bd24322dd623a0d27f75ad134f5087d972820b34815334e419b9764b7c061'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Es el buen Felipe de Meca, si va a llevar este curso, usted ya debió haber conocido a Felipe. Aprenda que es capa 8'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-15T00:00:00+00:00'::TIMESTAMPTZ, '179e19161a988f4e9e7382c5ad563e702929004dee3b91e90eeb5cac766e1549'::TEXT, ARRAY[3069]::BIGINT[]),
    (705::BIGINT, 'El curso es bastante demandante en términos de práctica, pero al final del día es una matemática más con una rúbrica bastante grosera (100% exámenes). Ir a las tutorías es un no negociable. El profe es muy pura vida y está dispuesto a ayudar. Las guías semanales no aportan mucho.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7eca183d447546034aac86949b28d9d0921b5e764c5ebb3a9f686fd29073e645'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'El curso es duro ya por si solo. El profe explica y aclara cualquier duda que usted tenga en clase, de verdad busca ayudar. Hay que ponerle y prácticar mucho por cuenta de uno, las tareas que deja el profe ayudan a eso. Sí se puede pasar el curso con él'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '02f6e1c7d20c33c5a14170f23189c8de858f77930af1295fed7a5d3b91902166'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'No le tenga miedo a matricular con él, solo póngale bastante. Le puede meter algo de miedo en las clases pero de verdad es excelente, va a aprender muchísimo con él, te amo felipe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-10-15T00:00:00+00:00'::TIMESTAMPTZ, '173b17c33604df41c9c5e402f15926ec268e57c5e6ceee7e9d17db23e02f96b8'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Es un buen profe, pero a la materia como tal hay que ponerle, porque es ruda. Si quiere aprender bien es con él, pero tiene que ponerle muucho tiempo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-26T00:00:00+00:00'::TIMESTAMPTZ, '9f844e1abb9467bf2fc47582b7bbf69b2ac5b5d2d5cb6f365a6ba5454d060a86'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'El profe es excelente. El curso es un curso dificil al que hay que tenerle respeto, pero tome tutorías de fijo porque son una salvada. Pero si usted quiere aprender bien este profe es el indicado, nada más póngale y se pasa'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd5853afe0e3c46d571f57c2ee70f4bf3fa7cc462ad10d00cf3aa3436b7064a10'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Es buen profe, explica muy bien. Tome las tutorías que recomienda son muy útiles de verdad. Sus exámenes no son difíciles a veces son ejercicios de tareas o del libro pero cambia algo. No subestime el curso y lo pasa a la primera sobre todo con este profe porque ayuda bastante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'bfb600e7e67260406732d03caaa32667a78a361ebac1f8f28f25395e72f103d4'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'La verdad, me quedé con este profe. No cometan el mismo error que yo y metan tutorías por que el profe califica DURO y no regala un punto (a veces da puntos anti-reclamos eso sí). Aún así, es un excelente profesor, yo me quedé por que subestimé el curso pero el profe es buenísimo, explica muy bien.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '743eb1f6a1b361590a3d9c22dd88db1fbb4fe85b0da2660c19ebb124f643d9be'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Es un gran profesor y se nota que le apasiona la materia. El curso es sencillo, pero un poco desordenado.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '4beea7bc585f80602060f5b7528609e711aabb70f39724b69b785a21ec574c7e'::TEXT, ARRAY[3069]::BIGINT[]),
    (705::BIGINT, 'Es un excelente profesor, las explicaciones son muy claras y si bien los exámenes son más difíciles respecto a los ejercicios de clase, la manera en la que enseña lo compensa. Siempre está atento a responder dudas. Tiene mucho conocimiento y sabe transmitirlo de buena manera.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'f186af91e58e99653ad4eeb89c695f231b5f70a723bf35ee105bb1b254a1362c'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'En general este profe, fuap, es una teja. Explica muy bien, ayuda mucho si se ocupa y hace las clases muy amenas. Su único defecto es que tarda en revisar las evaluaciones, pero quitando lo desorganizado es un profe excelente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Aspectos de calificación claros']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'db9a1ee8530a68d6ddfd4ec39933d5d9b770f45ccc9e6c90da56987c027e4956'::TEXT, ARRAY[3069]::BIGINT[]),
    (705::BIGINT, 'El profe es muy bueno. Considero que es necesario replantear algunas cosas del curso ya que está orientado al enfoque de Señales y sistemas, y modelos no es tan profundo. Deles la importancia necesaria a las tutorías. Las guías semanales no aportan tanto al aprendizaje, pero hágalas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd38a83c501163320625fbfa92a4f51259df0ab46adc6b28cc737686fcf75bfb2'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'Excelente profesor para este curso, el curso es muy difícil, pero él ayuda bastante y lo hace más ameno, los exámenes los hace a lo que vio en clase y si le pone bastante y estudia, pasa el curso'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ec524920d36c877fde1de8d58024de1816227267bf7f8337b7e5f4611085145e'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'El profe es demasiado bueno, top1 de profes de Meca de la nueva generación, el curso tenía muchas tareas, tqm Felipe :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'f54175bfd8c8ef1be9901a59124aab14abf9fd9b692115b7c142d85a5e9dbf63'::TEXT, ARRAY[3075]::BIGINT[]),
    (705::BIGINT, 'El curso es bastante complicado y con evaluaciones rudas, sin embargo el profe siempre explica súper bien en las clases, pero no es suficiente para estar listo para el examen. Califica duro las tareas y exámenes. Si le ofrece el programa de Tutorías, acepte, sube la nota por poco trabajo.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '8e975dc0ab25294909bdcb13ad85028bd0092dca08c9f6f89becc2cb82b8d1bd'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Es una teja, muy comprensivo con reclamos y ayudas. La clase es excelente para conceptos pero si uno no hace ejercicios por fuera, F en el examen. Acepte llevar las tutorías, son tediosas pero con solo ir y entregar la tarea se asegura un % que es MUY fácil perder en los exámenes.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a7b087aa11133f57e95d9fd5be6a66c422e93a78d649a869cad9f8e050054c23'::TEXT, ARRAY[3049]::BIGINT[]),
    (705::BIGINT, 'Uno de los mejores profesores a mi criterio, ayuda bastante con las guías al final si las hizo todas y atiende consultas. Eso si, él da lo básico, así que hay que estudiar muy independiente.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '0fe6381714f03e75dad2b71227e1569d0f61754fdb1561af2843e20082f684d6'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'De los mejores profesores de Mecatronica. Muy accesible como persona y profesor. El curso es de los más difíciles de la carrera sin embargo con este profe se hizo muy ameno. Califica justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '2ac4a6d1ffd2abe37d5f7c368ebe60a79d82b4ca86c199a3568f021d5aee9734'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'Lo mejor que le pudo pasar a este curso. Aunque las guías son tediosas y no aportan mucho al aprendizaje, el profe al final ayuda bastante con el redondeo si las entrega todas. Vaya a las tutorías, lo preparan bien para los exámenes y de paso le regalan el primer ejercicio.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '9a96f11db1257ebda3823132386eca7b72154e2f1e5bf168da4fb907ae27db47'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'En general es un buen profesor aunque a veces puede ser no muy claro en sus evaluaciones y entrega los resultados tarde. Pedía videos en lugar de defensas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '4f048666ce2120fa24a0437b841fd9acb433893c7eccd3eb905b11395b351784'::TEXT, ARRAY[3066]::BIGINT[]),
    (705::BIGINT, 'El profe explica muy claramente lo necesario para entender la materia del curso. A través del semestre, también motiva para sacar adelante el curso mediante práctica. Los ejercicios hechos en clase son bastante más fáciles que los de examen, entonces queda más al estudiante ponerle para pasar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '537cd736b9c808195924d4cf071167edf92ea225eb46582de9fe13a269b69643'::TEXT, ARRAY[3057]::BIGINT[]),
    (705::BIGINT, 'Simplemente lo mejor que llegó a Mecatrónica, un profe excelente, espero que le den más cursos, tienen que llevar con él alguna vez en sus vidas de Mecas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ce5cdfdffe825425b25f9399a847f7da2ea359eeb659917976eafb984df27fa6'::TEXT, ARRAY[3057]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
